# C10 text data only; tuple order: zh, en, fr, es, de, ru, ko, ja.
# 38 values, including the course title and three chapter titles; 304 fully expanded strings.

EXPORT_COPY = {
    "teaching_c10_title": ("导出与结果检查", "Export and check results", "Exporter et vérifier les résultats", "Exportar y comprobar resultados", "Exportieren und Ergebnisse prüfen", "Экспорт и проверка результатов", "내보내기와 결과 확인", "エクスポートと結果の確認"),
    "teaching_c10_formats_title": ("四种导出格式", "Four export formats", "Quatre formats d’export", "Cuatro formatos de exportación", "Vier Exportformate", "Четыре формата экспорта", "네 가지 내보내기 형식", "4 種類のエクスポート形式"),
    "teaching_c10_progress_cancel_title": ("导出进度与取消", "Export progress and cancellation", "Progression et annulation de l’export", "Progreso y cancelación de la exportación", "Exportfortschritt und Abbruch", "Ход экспорта и отмена", "내보내기 진행과 취소", "エクスポートの進行とキャンセル"),
    "teaching_c10_result_title": ("部分失败与重试", "Partial failure and retry", "Échec partiel et nouvelle tentative", "Fallo parcial y reintento", "Teilweise Fehler und erneuter Versuch", "Частичный сбой и повторная попытка", "부분 실패와 재시도", "一部失敗と再試行"),
    "teaching_c10_formats_intro_title": ("开始格式导出练习", "Start practicing export formats", "Commencer l’exercice des formats", "Comenzar la práctica de formatos", "Mit Exportformaten üben", "Начать упражнение с форматами", "내보내기 형식 연습 시작", "形式のエクスポート練習を始める"),
    "teaching_c10_formats_intro_body": ("本章用三页合成白板，分别导出 PNG、PDF、SVG 和 EPS 到当前私有练习目录。读完点击“下一步”，随后逐项确认全部页成功导出。", "Use the three-page synthetic board to export PNG, PDF, SVG, and EPS into this private practice. Read this introduction and click “Next step”; each later export must succeed for all three pages.", "Utilisez le tableau synthétique de trois pages pour exporter en PNG, PDF, SVG et EPS dans cet exercice privé. Lisez cette introduction puis cliquez sur « Étape suivante » ; chaque export doit réussir pour les trois pages.", "Usa la pizarra sintética de tres páginas para exportar PNG, PDF, SVG y EPS en esta práctica privada. Lee la introducción y pulsa « Paso siguiente »; cada exportación debe completar las tres páginas.", "Exportiere die synthetische Tafel mit drei Seiten in dieser privaten Übung als PNG, PDF, SVG und EPS. Lies die Einführung und klicke „Nächster Schritt“; jeder Export muss für alle drei Seiten gelingen.", "Экспортируйте синтетическую доску из трёх страниц в PNG, PDF, SVG и EPS в этом частном упражнении. Прочитайте введение и нажмите «Следующий шаг»; каждый экспорт должен успешно сохранить все три страницы.", "이 비공개 연습의 합성 3페이지 보드를 PNG, PDF, SVG, EPS로 각각 내보냅니다. 설명을 읽고 “다음 단계”를 누른 뒤 각 내보내기에서 세 페이지 모두 성공했는지 확인합니다.", "この非公開練習の合成 3 ページの白板を、PNG、PDF、SVG、EPS でそれぞれ出力します。説明を読んで「次の手順」を押し、各形式で全 3 ページの出力成功を確認します。"),
    "teaching_c10_formats_png_title": ("逐页导出 PNG", "Export PNG files for each page", "Exporter chaque page en PNG", "Exportar cada página como PNG", "Jede Seite als PNG exportieren", "Экспортировать страницы в PNG", "페이지별 PNG 내보내기", "各ページを PNG に出力する"),
    "teaching_c10_formats_png_body": ("点击文件栏的“PNG 图片”，将本练习三页逐页导出到私有目录。只有三页都实际写成 PNG 文件才完成，取消、失败或仅点击按钮都不算。", "Click “PNG Image” in the file panel to export this practice as three separate PNG files. Completion requires all three pages to be written successfully; cancellation, failure, or merely clicking does not count.", "Cliquez sur « Image PNG » dans le panneau des fichiers pour exporter les trois pages de cet exercice dans des fichiers séparés. Seule l’écriture réussie des trois PNG valide l’étape ; annuler ou cliquer seulement ne suffit pas.", "Pulsa « Imagen PNG » en el panel de archivos para exportar esta práctica como tres PNG separados. Solo se completa cuando se escriben las tres páginas correctamente; cancelar, fallar o pulsar sin resultado no cuenta.", "Klicke im Dateibereich auf „PNG-Bild“, um die drei Übungsseiten als getrennte PNG-Dateien zu exportieren. Alle drei müssen erfolgreich geschrieben werden; Abbruch, Fehler oder ein bloßer Klick zählen nicht.", "Нажмите «PNG-изображение» в панели файлов, чтобы экспортировать три страницы упражнения в отдельные PNG. Шаг засчитывается только после успешной записи всех трёх; отмена, сбой или одно нажатие не подходят.", "파일 패널에서 “PNG 이미지”를 눌러 이 연습의 세 페이지를 각각 PNG 파일로 내보냅니다. 세 페이지 모두 실제로 저장되어야 완료되며 취소, 실패, 버튼 클릭만으로는 인정되지 않습니다.", "ファイルパネルの「PNG 画像」を押し、練習の 3 ページを別々の PNG ファイルとして出力します。全 3 ページの書き込み成功が必要で、キャンセル、失敗、クリックだけでは完了しません。"),
    "teaching_c10_formats_pdf_title": ("导出一个多页 PDF", "Export one PDF with all pages", "Exporter un PDF de plusieurs pages", "Exportar un PDF con todas las páginas", "Ein PDF mit allen Seiten exportieren", "Экспортировать один многостраничный PDF", "모든 페이지를 하나의 PDF로 내보내기", "全ページを 1 つの PDF に出力する"),
    "teaching_c10_formats_pdf_body": ("点击文件栏的“PDF 文档”，将三页白板导出为一个三页 PDF 文件。只有全部页成功且文件完成提交才算完成，部分文件、失败或取消都不算。", "Click “PDF Document” in the file panel to export the three board pages into one three-page PDF. Completion requires every page and the final file to succeed; partial output, failure, or cancellation does not count.", "Cliquez sur « Document PDF » dans le panneau des fichiers pour réunir les trois pages du tableau dans un PDF de trois pages. Toutes les pages et le fichier final doivent réussir ; une sortie partielle ou annulée ne compte pas.", "Pulsa « Documento PDF » en el panel de archivos para reunir las tres páginas de la pizarra en un PDF. Deben completarse todas las páginas y confirmarse el archivo final; un resultado parcial, fallo o cancelación no cuenta.", "Klicke im Dateibereich auf „PDF-Dokument“, um die drei Tafelseiten in einer PDF-Datei mit drei Seiten zu speichern. Alle Seiten und die endgültige Datei müssen gelingen; Teilergebnis, Fehler oder Abbruch zählen nicht.", "Нажмите «PDF-документ» в панели файлов, чтобы сохранить три страницы доски в один трёхстраничный PDF. Нужны успешный экспорт всех страниц и фиксация итогового файла; частичный результат, ошибка или отмена не подходят.", "파일 패널에서 “PDF 문서”를 눌러 보드의 세 페이지를 하나의 3페이지 PDF로 내보냅니다. 모든 페이지와 최종 파일 제출이 성공해야 하며 부분 결과, 실패, 취소는 완료가 아닙니다.", "ファイルパネルの「PDF 文書」を押し、白板の 3 ページを 1 つの 3 ページ PDF に出力します。全ページと最終ファイルの確定が成功する必要があり、一部出力、失敗、キャンセルは完了になりません。"),
    "teaching_c10_formats_svg_title": ("逐页导出 SVG", "Export SVG files for each page", "Exporter chaque page en SVG", "Exportar cada página como SVG", "Jede Seite als SVG exportieren", "Экспортировать страницы в SVG", "페이지별 SVG 내보내기", "各ページを SVG に出力する"),
    "teaching_c10_formats_svg_body": ("点击文件栏的“SVG 矢量图”，将三页合成白板分别导出为 SVG 文件。必须三页全部成功；此处练习线段和几何，不表示任意位图都会自动变成矢量图形。", "Click “SVG Vector” in the file panel to export three separate SVG files from the synthetic board. All pages must succeed; this exercise uses lines and geometry, without automatically converting arbitrary bitmaps into vector shapes.", "Cliquez sur « Vectoriel SVG » dans le panneau des fichiers pour exporter le tableau synthétique en trois SVG séparés. Chaque page doit réussir ; cet exercice utilise des lignes et des formes, sans vectoriser automatiquement des images quelconques.", "Pulsa « Vector SVG » en el panel de archivos para exportar la pizarra sintética como tres SVG separados. Todas las páginas deben completarse; practicar líneas y geometría no convierte automáticamente imágenes arbitrarias en formas vectoriales.", "Klicke im Dateibereich auf „SVG-Vektor“, um die synthetische Tafel in drei getrennte SVG-Dateien zu exportieren. Alle Seiten müssen gelingen; Linien und Geometrie in dieser Übung bedeuten keine automatische Vektorisierung beliebiger Bitmaps.", "Нажмите «SVG-вектор» в панели файлов, чтобы экспортировать синтетическую доску в три отдельных SVG. Все страницы должны сохраниться; линии и геометрия этого упражнения не означают автоматическую векторизацию любых растровых изображений.", "파일 패널에서 “SVG 벡터”를 눌러 합성 보드 세 페이지를 각각 SVG 파일로 내보냅니다. 모두 성공해야 하며, 선과 도형을 연습한다고 임의의 비트맵이 자동으로 벡터 도형으로 변환되는 것은 아닙니다.", "ファイルパネルの「SVG ベクター」を押し、合成白板の 3 ページを別々の SVG ファイルに出力します。全ページの成功が必要で、線や図形の練習は任意のビットマップの自動ベクター化を意味しません。"),
    "teaching_c10_formats_eps_title": ("逐页导出 EPS", "Export EPS files for each page", "Exporter chaque page en EPS", "Exportar cada página como EPS", "Jede Seite als EPS exportieren", "Экспортировать страницы в EPS", "페이지별 EPS 내보내기", "各ページを EPS に出力する"),
    "teaching_c10_formats_eps_body": ("点击文件栏的“EPS 矢量图”，将三页合成白板分别导出为 EPS 文件。必须看到三页全部成功的结果；格式名称不保证任意图片都会转换成可编辑矢量内容。", "Click “EPS Vector” in the file panel to export three separate EPS files from the synthetic board. Every page must succeed; the format name does not guarantee conversion of arbitrary images into editable vector content.", "Cliquez sur « Vectoriel EPS » dans le panneau des fichiers pour exporter le tableau synthétique en trois EPS séparés. Chaque page doit réussir ; le nom du format ne garantit pas la conversion de toute image en contenu vectoriel modifiable.", "Pulsa « Vector EPS » en el panel de archivos para exportar la pizarra sintética como tres EPS separados. Todas las páginas deben completarse; el nombre del formato no garantiza convertir cualquier imagen en contenido vectorial editable.", "Klicke im Dateibereich auf „EPS-Vektor“, um die synthetische Tafel in drei getrennte EPS-Dateien zu exportieren. Jede Seite muss gelingen; der Formatname garantiert nicht, dass beliebige Bilder in bearbeitbare Vektorinhalte umgewandelt werden.", "Нажмите «EPS-вектор» в панели файлов, чтобы экспортировать синтетическую доску в три отдельных EPS. Все страницы должны сохраниться; название формата не гарантирует превращения любых изображений в редактируемое векторное содержимое.", "파일 패널에서 “EPS 벡터”를 눌러 합성 보드 세 페이지를 각각 EPS 파일로 내보냅니다. 모든 페이지가 성공해야 하며, 형식 이름만으로 임의의 이미지가 편집 가능한 벡터 내용으로 변환되는 것은 아닙니다.", "ファイルパネルの「EPS ベクター」を押し、合成白板の 3 ページを別々の EPS ファイルに出力します。全ページの成功が必要で、形式名は任意の画像を編集可能なベクターに変換する保証ではありません。"),
    "teaching_c10_formats_formats_info_title": ("核对各格式的文件组织", "Review how formats organize files", "Vérifier les fichiers de chaque format", "Revisar los archivos de cada formato", "Dateien der Formate vergleichen", "Проверить файлы разных форматов", "형식별 파일 구성 확인", "各形式のファイル構成を確認する"),
    "teaching_c10_formats_formats_info_body": ("本练习的 PNG、SVG、EPS 每页各一个文件，PDF 则把三页放在一个文件中。核对结果中的成功页数后点击“下一步”，格式名称不等于每页都已导出。", "PNG, SVG, and EPS produce one file per page here, while PDF contains all three pages in one file. Review the successful page counts, then click “Next step”; a format name alone proves nothing.", "PNG, SVG et EPS produisent ici un fichier par page, tandis que PDF réunit les trois pages dans un seul fichier. Vérifiez le nombre de pages réussies puis cliquez sur « Étape suivante » ; le nom du format ne suffit pas.", "PNG, SVG y EPS generan aquí un archivo por página, mientras que PDF reúne las tres en un solo archivo. Revisa cuántas páginas se completaron y pulsa « Paso siguiente »; el nombre del formato no basta.", "PNG, SVG und EPS erzeugen hier eine Datei je Seite, PDF enthält dagegen alle drei Seiten in einer Datei. Prüfe die Anzahl erfolgreich exportierter Seiten und klicke „Nächster Schritt“; der Formatname allein genügt nicht.", "PNG, SVG и EPS создают здесь отдельный файл для каждой страницы, а PDF содержит все три в одном файле. Проверьте число успешно сохранённых страниц и нажмите «Следующий шаг»; одного названия формата недостаточно.", "이 연습에서 PNG, SVG, EPS는 페이지마다 파일 하나를 만들고 PDF는 세 페이지를 한 파일에 담습니다. 성공한 페이지 수를 확인한 뒤 “다음 단계”를 누르며, 형식 이름만으로 모두 내보냈다고 판단하지 않습니다.", "この練習では PNG、SVG、EPS は各ページ 1 ファイル、PDF は全 3 ページで 1 ファイルです。成功したページ数を確認して「次の手順」を押し、形式名だけで全ページ出力済みと判断しないでください。"),
    "teaching_c10_formats_done_title": ("完成格式导出练习", "Finish the export formats practice", "Terminer l’exercice des formats", "Terminar la práctica de formatos", "Exportformatübung abschließen", "Завершить упражнение с форматами", "내보내기 형식 연습 완료", "形式のエクスポート練習を完了する"),
    "teaching_c10_formats_done_body": ("确认四种格式都已导出本练习全部三页，再点击“下一步”确认本章。需要换章或返回原工作时，在教学中心选择章节或使用“退出教学”。", "Confirm that each of the four formats exported all three practice pages, then click “Next step” to confirm this chapter. Use the tutorial center or “Exit tutorial” to choose another chapter or return.", "Vérifiez que les quatre formats ont exporté les trois pages puis cliquez sur « Étape suivante » pour confirmer ce chapitre. Choisissez un autre chapitre dans le centre ou utilisez « Quitter le tutoriel » pour revenir.", "Confirma que los cuatro formatos exportaron las tres páginas y pulsa « Paso siguiente » para confirmar este capítulo. Elige otro capítulo en el centro o usa « Salir del tutorial » para volver al trabajo original.", "Bestätige, dass alle vier Formate sämtliche drei Übungsseiten exportiert haben, und klicke „Nächster Schritt“. Wähle im Tutorialzentrum ein weiteres Kapitel oder nutze „Tutorial beenden“, um zur ursprünglichen Arbeit zurückzukehren.", "Убедитесь, что все четыре формата сохранили все три страницы, и нажмите «Следующий шаг», чтобы подтвердить главу. Другую главу выбирают в центре обучения, а «Выйти из обучения» возвращает к исходной работе.", "네 가지 형식 모두 연습의 세 페이지를 내보냈는지 확인하고 “다음 단계”로 이 장을 확인합니다. 다른 장은 교육 센터에서 선택하고 원래 작업으로 돌아갈 때는 “튜토리얼 종료”를 사용합니다.", "4 形式とも練習の全 3 ページを出力したことを確認し、「次の手順」でこの章を確定します。別の章は学習センターで選び、元の作業に戻るときは「チュートリアルを終了」を使います。"),
    "teaching_c10_progress_cancel_intro_title": ("开始导出取消练习", "Start practicing export cancellation", "Commencer l’exercice d’annulation", "Comenzar la práctica de cancelación", "Mit dem Exportabbruch üben", "Начать упражнение с отменой", "내보내기 취소 연습 시작", "エクスポートのキャンセル練習を始める"),
    "teaching_c10_progress_cancel_intro_body": ("本章使用二十四页合成白板，练习在真实导出进度框中取消 PNG 导出。读完点击“下一步”，随后以实际取消终态确认操作，而不是只看见进度框。", "This chapter uses a synthetic board with twenty-four pages to practice cancelling PNG export in its real progress dialog. Read the introduction and click “Next step”; the operation needs an actual cancelled result.", "Ce chapitre utilise un tableau synthétique de vingt-quatre pages pour annuler un export PNG dans son véritable dialogue de progression. Lisez l’introduction puis cliquez sur « Étape suivante » ; l’opération exige un résultat réellement annulé.", "Este capítulo usa una pizarra sintética de veinticuatro páginas para cancelar una exportación PNG en su diálogo real de progreso. Lee la introducción y pulsa « Paso siguiente »; la operación requiere un resultado realmente cancelado.", "Dieses Kapitel verwendet eine synthetische Tafel mit vierundzwanzig Seiten, um den PNG-Export im echten Fortschrittsdialog abzubrechen. Lies die Einführung und klicke „Nächster Schritt“; die Aktion braucht ein tatsächlich abgebrochenes Ergebnis.", "В этой главе используется синтетическая доска из двадцати четырёх страниц для отмены PNG-экспорта в настоящем окне хода операции. Прочитайте введение и нажмите «Следующий шаг»; нужен фактический итог отмены.", "이 장에서는 합성 24페이지 보드로 실제 진행 창에서 PNG 내보내기를 취소하는 연습을 합니다. 설명을 읽고 “다음 단계”를 누르며, 창을 보는 것만이 아니라 실제 취소 결과가 필요합니다.", "この章では合成 24 ページの白板を使い、実際の進行ダイアログで PNG 出力をキャンセルします。説明を読んで「次の手順」を押し、進行画面を見るだけでなく実際のキャンセル結果を確認します。"),
    "teaching_c10_progress_cancel_cancel_png_title": ("在进度框取消 PNG 导出", "Cancel PNG export during progress", "Annuler l’export PNG en cours", "Cancelar PNG durante el progreso", "PNG-Export im Fortschritt abbrechen", "Отменить PNG-экспорт во время работы", "진행 창에서 PNG 내보내기 취소", "進行中の PNG 出力をキャンセルする"),
    "teaching_c10_progress_cancel_cancel_png_body": ("点击“PNG 图片”开始导出，再在真实进度框中点击“取消”。必须得到实际取消结果；若全部页已太快导完，本次不算取消，可再次开始并在进度期间重试。", "Click “PNG Image”, then click “Cancel” in the actual export progress dialog before export finishes. This step requires a cancelled result; if all pages finish first, start another attempt and cancel during progress.", "Cliquez sur « Image PNG », puis sur « Annuler » dans le véritable dialogue de progression avant la fin de l’export. Il faut un résultat annulé ; si toutes les pages sont déjà terminées, recommencez et annulez pendant la progression.", "Pulsa « Imagen PNG » y después « Cancelar » en el diálogo real de progreso antes de terminar la exportación. Se requiere un resultado cancelado; si todas las páginas terminan primero, vuelve a iniciar y cancela durante el progreso.", "Klicke auf „PNG-Bild“ und anschließend auf „Abbrechen“ im echten Fortschrittsdialog, bevor der Export endet. Es muss ein Abbruchergebnis entstehen; sind alle Seiten schon fertig, starte einen neuen Versuch und brich während des Fortschritts ab.", "Нажмите «PNG-изображение», затем «Отмена» в настоящем окне хода экспорта до его завершения. Нужен итог отмены; если все страницы уже сохранены, начните ещё раз и отмените операцию во время работы.", "“PNG 이미지”로 내보내기를 시작하고 완료 전에 실제 진행 창의 “취소”를 누릅니다. 실제 취소 결과가 있어야 하며, 이미 모든 페이지가 끝났다면 다시 시작해 진행 중 취소를 재시도합니다.", "「PNG 画像」で出力を開始し、完了前に実際の進行ダイアログの「キャンセル」を押します。実際のキャンセル結果が必要で、全ページが先に完了した場合はもう一度開始して進行中に試してください。"),
    "teaching_c10_progress_cancel_cancel_info_title": ("核对取消后的保留文件", "Review files retained after cancellation", "Vérifier les fichiers après annulation", "Revisar archivos tras cancelar", "Dateien nach dem Abbruch prüfen", "Проверить файлы после отмены", "취소 후 남은 파일 확인", "キャンセル後に残ったファイルを確認する"),
    "teaching_c10_progress_cancel_cancel_info_body": ("取消会保留已经写好的 PNG 文件，尚未导出的页不算成功。核对取消结果和实际已导出页数后点击“下一步”，不要把本次取消当成全部完成。", "Cancelling keeps any PNG files already written, while pages not exported remain incomplete. Review the cancelled result and the number of pages actually exported, then click “Next step” without treating cancellation as full success.", "L’annulation conserve les PNG déjà écrits, tandis que les pages non exportées restent incomplètes. Vérifiez le résultat annulé et le nombre de pages réellement exportées, puis cliquez sur « Étape suivante » sans y voir une réussite complète.", "Cancelar conserva los PNG ya escritos, mientras que las páginas no exportadas siguen incompletas. Revisa el resultado cancelado y cuántas páginas se exportaron realmente, y pulsa « Paso siguiente » sin considerarlo un éxito completo.", "Ein Abbruch behält bereits geschriebene PNG-Dateien bei; nicht exportierte Seiten bleiben unvollständig. Prüfe das Abbruchergebnis und die Anzahl tatsächlich exportierter Seiten und klicke „Nächster Schritt“, ohne den Abbruch als vollständigen Erfolg zu werten.", "Отмена сохраняет уже записанные PNG, а неэкспортированные страницы остаются незавершёнными. Проверьте итог отмены и число фактически сохранённых страниц, затем нажмите «Следующий шаг», не считая отмену полным успехом.", "취소해도 이미 저장된 PNG 파일은 남으며 아직 내보내지 않은 페이지는 성공으로 계산하지 않습니다. 취소 결과와 실제 내보낸 페이지 수를 확인하고 “다음 단계”를 누르되 전체 성공으로 판단하지 않습니다.", "キャンセルしても書き込み済みの PNG は残り、まだ出力していないページは成功に数えません。キャンセル結果と実際の出力ページ数を確認して「次の手順」を押し、全ページ成功とみなさないでください。"),
    "teaching_c10_progress_cancel_done_title": ("完成取消练习", "Finish the cancellation practice", "Terminer l’exercice d’annulation", "Terminar la práctica de cancelación", "Abbruchübung abschließen", "Завершить упражнение с отменой", "취소 연습 완료", "キャンセル練習を完了する"),
    "teaching_c10_progress_cancel_done_body": ("确认已经得到实际取消结果，并理解已写文件保留和未导出页未完成的区别。点击“下一步”只确认本章，不会自动补导出、切换章节或退出教学。", "Confirm that an actual cancelled result occurred and that written files remain while unexported pages stay incomplete. Click “Next step” to confirm this chapter only; it does not export remaining pages or change chapters automatically.", "Vérifiez qu’un résultat réellement annulé a eu lieu et que les fichiers écrits restent présents tandis que les pages restantes sont incomplètes. Cliquez sur « Étape suivante » pour confirmer ce chapitre ; les pages restantes ne sont pas exportées automatiquement.", "Confirma que hubo un resultado realmente cancelado y que los archivos escritos se conservan mientras las páginas restantes siguen incompletas. Pulsa « Paso siguiente » para confirmar solo este capítulo; no se completa la exportación ni se cambia de capítulo automáticamente.", "Bestätige den tatsächlichen Abbruch und den Unterschied zwischen behaltenen Dateien und unvollständigen Seiten. Klicke „Nächster Schritt“, um nur dieses Kapitel zu bestätigen; verbleibende Seiten werden weder automatisch exportiert noch wird das Kapitel gewechselt.", "Убедитесь, что операция действительно отменена, и различайте сохранённые файлы и незавершённые страницы. Нажмите «Следующий шаг», чтобы подтвердить только эту главу; оставшиеся страницы не экспортируются автоматически, а глава не переключается.", "실제 취소 결과가 있었고 저장된 파일은 남지만 미출력 페이지는 미완료임을 확인합니다. “다음 단계”는 이 장만 확인하며 남은 페이지 내보내기, 장 전환, 교육 종료를 자동으로 수행하지 않습니다.", "実際のキャンセル結果があり、書き込み済みファイルは残り、未出力ページは未完了であることを確認します。「次の手順」はこの章だけを確定し、残りの出力や章の移動、学習終了は自動で行いません。"),
    "teaching_c10_result_intro_title": ("开始部分失败与重试练习", "Start practicing partial failure and retry", "Commencer l’exercice d’échec partiel", "Comenzar la práctica de fallo parcial", "Mit Teilergebnissen und Wiederholung üben", "Начать упражнение с частичным сбоем", "부분 실패와 재시도 연습 시작", "一部失敗と再試行の練習を始める"),
    "teaching_c10_result_intro_body": ("本章用三页合成白板和私有示例路径冲突，先观察部分失败，再完成一次重试。读完点击“下一步”，两次导出都以真实文件结果判定。", "This chapter uses a three-page synthetic board and a private sample path conflict to show partial failure before a retry. Read the introduction and click “Next step”; both exports require real file results.", "Ce chapitre utilise un tableau synthétique de trois pages et un conflit de chemin privé pour montrer un échec partiel avant une nouvelle tentative. Lisez l’introduction puis cliquez sur « Étape suivante » ; les deux exports exigent des résultats réels.", "Este capítulo usa una pizarra sintética de tres páginas y un conflicto de ruta privado para mostrar un fallo parcial antes de reintentar. Lee la introducción y pulsa « Paso siguiente »; ambas exportaciones requieren resultados de archivo reales.", "Dieses Kapitel verwendet eine synthetische Tafel mit drei Seiten und einen privaten Pfadkonflikt, um ein Teilergebnis vor der Wiederholung zu zeigen. Lies die Einführung und klicke „Nächster Schritt“; beide Exporte brauchen echte Dateiergebnisse.", "В этой главе синтетическая доска из трёх страниц и частный конфликт пути показывают частичный сбой перед повторной попыткой. Прочитайте введение и нажмите «Следующий шаг»; обе операции оцениваются по реальным файлам.", "이 장은 합성 3페이지 보드와 비공개 예제 경로 충돌로 부분 실패를 확인한 뒤 재시도합니다. 설명을 읽고 “다음 단계”를 누르며 두 내보내기 모두 실제 파일 결과로 판단합니다.", "この章では合成 3 ページの白板と非公開の例題用パス競合で一部失敗を確認し、再試行します。説明を読んで「次の手順」を押し、2 回とも実際のファイル結果で判定します。"),
    "teaching_c10_result_partial_png_title": ("观察两页成功、一页失败", "Observe two pages succeed and one fail", "Observer deux réussites et un échec", "Ver dos páginas correctas y una fallida", "Zwei Erfolge und einen Fehler beobachten", "Наблюдать две успешные страницы и одну ошибку", "두 페이지 성공과 한 페이지 실패 확인", "2 ページ成功と 1 ページ失敗を確認する"),
    "teaching_c10_result_partial_png_body": ("点击“PNG 图片”，本次导出会遇到私有示例路径冲突，实际写出两页并使一页失败。查看结果中的失败页和已成功文件，不能把此结果当成三页全部成功。", "Click “PNG Image”; this export encounters the private sample path conflict and actually writes two pages while one fails. Review the failed page and successful files in the result, without treating it as full success.", "Cliquez sur « Image PNG » ; cet export rencontre le conflit de chemin privé et écrit réellement deux pages tandis qu’une échoue. Consultez la page en échec et les fichiers réussis sans considérer le résultat comme complet.", "Pulsa « Imagen PNG »; esta exportación encuentra el conflicto de ruta privado y escribe dos páginas mientras una falla. Revisa la página fallida y los archivos correctos del resultado, sin considerarlo un éxito completo.", "Klicke auf „PNG-Bild“; dieser Export stößt auf den privaten Pfadkonflikt und schreibt tatsächlich zwei Seiten, während eine fehlschlägt. Prüfe die fehlerhafte Seite und die erfolgreichen Dateien, ohne das Ergebnis als vollständigen Erfolg zu werten.", "Нажмите «PNG-изображение»; экспорт встретит частный конфликт пути и действительно сохранит две страницы, а одна завершится ошибкой. Проверьте проблемную страницу и успешно записанные файлы, не считая это полным успехом.", "“PNG 이미지”를 누르면 비공개 예제 경로 충돌로 두 페이지는 실제로 저장되고 한 페이지는 실패합니다. 결과에서 실패한 페이지와 성공한 파일을 확인하며 세 페이지 전체 성공으로 판단하지 않습니다.", "「PNG 画像」を押すと例題用の非公開パス競合により、2 ページが実際に書き込まれ、1 ページは失敗します。結果の失敗ページと成功したファイルを確認し、全 3 ページ成功とみなさないでください。"),
    "teaching_c10_result_partial_info_title": ("区分部分失败与完整成功", "Distinguish partial failure from full success", "Distinguer échec partiel et réussite complète", "Distinguir fallo parcial de éxito completo", "Teilergebnis von vollem Erfolg unterscheiden", "Отличить частичный сбой от полного успеха", "부분 실패와 전체 성공 구분", "一部失敗と全ページ成功を区別する"),
    "teaching_c10_result_partial_info_body": ("本次结果的失败列表对应第二页，已成功写好的第一页和第三页文件会保留。读完点击“下一步”，已尝试全部页不等于全部页导出成功。", "The failure list identifies page two, while successfully written files for pages one and three remain available. Read this explanation and click “Next step”; attempting every page does not mean every page exported successfully.", "La liste des échecs désigne la deuxième page, tandis que les fichiers réussis des pages une et trois restent présents. Lisez puis cliquez sur « Étape suivante » ; tenter toutes les pages ne signifie pas les avoir toutes exportées.", "La lista de errores señala la segunda página y los archivos correctos de la primera y la tercera se conservan. Lee y pulsa « Paso siguiente »; intentar todas las páginas no significa haberlas exportado correctamente.", "Die Fehlerliste nennt Seite zwei, während die erfolgreich geschriebenen Dateien für Seite eins und drei erhalten bleiben. Lies die Erklärung und klicke „Nächster Schritt“; alle Seiten versucht zu haben bedeutet keinen vollständigen Exporterfolg.", "Список ошибок указывает вторую страницу, а успешно записанные файлы первой и третьей сохраняются. Прочитайте пояснение и нажмите «Следующий шаг»; попытка обработать все страницы не означает успешный экспорт каждой.", "실패 목록은 두 번째 페이지를 가리키며 성공한 첫 번째와 세 번째 페이지 파일은 남아 있습니다. 설명을 읽고 “다음 단계”를 누르며 모든 페이지를 시도한 것과 모두 성공한 것을 구분합니다.", "失敗一覧は 2 ページ目を示し、書き込みに成功した 1 ページ目と 3 ページ目のファイルは残ります。説明を読んで「次の手順」を押し、全ページを試したことと全ページの成功を区別してください。"),
    "teaching_c10_result_retry_png_title": ("重试并导出全部三页", "Retry and export all three pages", "Réessayer et exporter les trois pages", "Reintentar y exportar las tres páginas", "Erneut alle drei Seiten exportieren", "Повторить экспорт всех трёх страниц", "재시도하여 세 페이지 모두 내보내기", "再試行して全 3 ページを出力する"),
    "teaching_c10_result_retry_png_body": ("再次点击“PNG 图片”重试，本练习会在这次导出前移除私有示例障碍。只有三页都实际成功写出才完成，这种练习内清理不表示正常使用会自动修复所有错误。", "Click “PNG Image” again; this practice removes its private sample obstacle before the retry begins. Completion requires all three pages to be written successfully, and this exercise cleanup does not automatically fix ordinary export errors.", "Cliquez à nouveau sur « Image PNG » ; cet exercice retire son obstacle privé avant la nouvelle tentative. Les trois pages doivent être écrites avec succès, et ce nettoyage pédagogique ne corrige pas automatiquement les erreurs d’export courantes.", "Pulsa otra vez « Imagen PNG »; esta práctica elimina su obstáculo privado antes del reintento. Deben escribirse las tres páginas correctamente, y esta limpieza del ejercicio no corrige automáticamente los errores normales de exportación.", "Klicke erneut auf „PNG-Bild“; diese Übung entfernt ihren privaten Beispielkonflikt vor der Wiederholung. Alle drei Seiten müssen erfolgreich geschrieben werden; diese Übungsbereinigung behebt normale Exportfehler nicht automatisch.", "Снова нажмите «PNG-изображение»; упражнение удалит свой частный пример препятствия перед повтором. Все три страницы должны успешно сохраниться, а такая учебная очистка не исправляет автоматически обычные ошибки экспорта.", "“PNG 이미지”를 다시 누르면 이번 연습은 재시도 시작 전에 비공개 예제 장애물을 제거합니다. 세 페이지 모두 실제로 저장되어야 하며 이 연습의 정리가 일반 내보내기 오류를 자동으로 고치는 것은 아닙니다.", "もう一度「PNG 画像」を押すと、この練習では再試行前に非公開の例題用障害を取り除きます。全 3 ページの書き込み成功が必要で、この練習内の処理が通常のエクスポートエラーをすべて自動修復するわけではありません。"),
    "teaching_c10_result_success_info_title": ("核对重试后的完整结果", "Review the complete retry result", "Vérifier le résultat complet du nouvel essai", "Revisar el resultado completo del reintento", "Vollständiges Wiederholungsergebnis prüfen", "Проверить полный результат повтора", "재시도 전체 결과 확인", "再試行の全ページ成功を確認する"),
    "teaching_c10_result_success_info_body": ("本次重试应实际导出三页且没有失败页，正常使用遇错时应先检查原因并修正再重试。读完点击“下一步”，不要从本练习的示例清理推断任何错误都会自动修好。", "This retry must actually export all three pages without failures; in ordinary use, investigate and correct an error before retrying. Read this explanation and click “Next step”, without expecting the practice cleanup to fix everything.", "Cette nouvelle tentative doit exporter les trois pages sans échec ; en usage normal, recherchez et corrigez la cause avant de réessayer. Lisez puis cliquez sur « Étape suivante », sans attendre que le nettoyage pédagogique répare tout.", "El reintento debe exportar las tres páginas sin errores; en el uso normal, averigua y corrige la causa antes de reintentar. Lee y pulsa « Paso siguiente », sin esperar que la limpieza del ejercicio lo arregle todo.", "Die Wiederholung muss alle drei Seiten ohne Fehler exportieren; im normalen Gebrauch prüfst und behebst du die Ursache vor dem erneuten Versuch. Lies die Erklärung und klicke „Nächster Schritt“, ohne von der Übungsbereinigung eine allgemeine Reparatur zu erwarten.", "Повтор должен действительно сохранить все три страницы без ошибок; при обычной работе сначала выясните и устраните причину сбоя. Прочитайте пояснение и нажмите «Следующий шаг», не ожидая, что учебная очистка исправит всё.", "이번 재시도는 세 페이지를 실패 없이 실제로 내보내야 하며 평소에는 먼저 오류 원인을 확인하고 고친 뒤 재시도해야 합니다. 설명을 읽고 “다음 단계”를 누르며 연습용 정리가 모든 오류를 해결한다고 기대하지 않습니다.", "再試行では全 3 ページを失敗なく実際に出力し、通常の使用では原因を調べて修正してから試し直します。説明を読んで「次の手順」を押し、練習用の処理がすべてのエラーを直すとは考えないでください。"),
    "teaching_c10_result_done_title": ("完成结果检查练习", "Finish the export result practice", "Terminer l’exercice des résultats", "Terminar la práctica de resultados", "Ergebnisprüfung abschließen", "Завершить проверку результатов", "내보내기 결과 연습 완료", "結果確認の練習を完了する"),
    "teaching_c10_result_done_body": ("确认已经观察真实部分失败，并通过重试完成三页全部导出。点击“下一步”只确认本章，随后可在教学中心换章或使用“退出教学”返回原工作。", "Confirm that you observed real partial failure and then successfully exported all three pages on retry. Click “Next step” to confirm this chapter; choose another chapter in the center or use “Exit tutorial” afterward.", "Vérifiez que vous avez observé un véritable échec partiel puis exporté les trois pages avec succès lors du nouvel essai. Cliquez sur « Étape suivante » pour confirmer ce chapitre, puis choisissez un autre chapitre ou utilisez « Quitter le tutoriel ».", "Confirma que observaste un fallo parcial real y luego exportaste las tres páginas correctamente al reintentar. Pulsa « Paso siguiente » para confirmar este capítulo y después elige otro en el centro o usa « Salir del tutorial ».", "Bestätige, dass du ein echtes Teilergebnis beobachtet und anschließend alle drei Seiten erfolgreich exportiert hast. Klicke „Nächster Schritt“, um dieses Kapitel zu bestätigen, und wähle danach ein weiteres oder nutze „Tutorial beenden“.", "Убедитесь, что наблюдали реальный частичный сбой, а затем успешно сохранили все три страницы при повторе. Нажмите «Следующий шаг», чтобы подтвердить главу, затем выберите другую в центре или используйте «Выйти из обучения».", "실제 부분 실패를 확인한 뒤 재시도에서 세 페이지 모두 성공적으로 내보냈는지 확인합니다. “다음 단계”로 이 장만 확인한 후 교육 센터에서 다른 장을 선택하거나 “튜토리얼 종료”로 원래 작업에 돌아갑니다.", "実際の一部失敗を確認し、再試行で全 3 ページの出力に成功したことを確認します。「次の手順」でこの章だけを確定し、その後は学習センターで章を選ぶか「チュートリアルを終了」で元の作業に戻ります。"),
}
